package com.novalearn.application.auth;
import com.novalearn.domain.auth.Role; import org.junit.jupiter.api.*; import java.util.*; import static org.assertj.core.api.Assertions.*; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*;
class AuthServiceTest {
 private final ParentAccountRepository accounts=mock(ParentAccountRepository.class); private final PasswordHasher passwords=mock(PasswordHasher.class); private final TokenService tokens=mock(TokenService.class); private final AuthService service=new AuthService(accounts,passwords,tokens);
 @Test void registers_normalized_email_and_issues_token(){ when(accounts.save(any())).thenAnswer(i->i.getArgument(0)); when(tokens.issue(any(),eq(Role.PARENT))).thenReturn("token"); when(passwords.hash("A secure password")).thenReturn("hash");
  AuthService.AuthResult result=service.register("  PARENT@Example.COM ","A secure password"); assertThat(result.email()).isEqualTo("parent@example.com"); assertThat(result.accessToken()).isEqualTo("token"); verify(passwords).hash("A secure password"); }
 @Test void rejects_existing_email(){when(accounts.existsByEmail("parent@example.com")).thenReturn(true); assertThatThrownBy(()->service.register("parent@example.com","A secure password")).isInstanceOf(EmailAlreadyRegisteredException.class); verifyNoInteractions(passwords,tokens);}
 @Test void rejects_invalid_password_without_issuing_token(){ParentAccount p=new ParentAccount(UUID.randomUUID(),"parent@example.com","hash",Role.PARENT);when(accounts.findByEmail(p.email())).thenReturn(Optional.of(p));when(passwords.matches("wrong",p.passwordHash())).thenReturn(false);assertThatThrownBy(()->service.authenticate(p.email(),"wrong")).isInstanceOf(AuthenticationException.class);verifyNoInteractions(tokens);}
 @Test void does_not_distinguish_an_unknown_email(){when(accounts.findByEmail("missing@example.com")).thenReturn(Optional.empty());assertThatThrownBy(()->service.authenticate("missing@example.com","a password")).isInstanceOf(AuthenticationException.class);verifyNoInteractions(tokens,passwords);}
}
